-- `GENERATED BY DEFAULT AS IDENTITY` behaves like SERIAL: an omitted value draws
-- the next sequence number, and an explicit value (50) is used as-is (without
-- advancing the sequence, so the following omitted insert is 2, not 51).
-- @setup
CREATE TABLE t (id int GENERATED BY DEFAULT AS IDENTITY, name text);
INSERT INTO t (name) VALUES ('a');
INSERT INTO t (id, name) VALUES (50, 'explicit');
INSERT INTO t (name) VALUES ('c');
-- @test
SELECT id, name FROM t ORDER BY name;
